function openJournal(chunks) {
  let iterator;
  let acquired = false;
  let ended = false;
  let returnStarted = false;
  let returnPromise;

  let chunk = new Uint8Array(0);
  let offset = 0;
  let line = 1;
  let text = "";
  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

  function done() {
    return { done: true, value: undefined };
  }

  function release() {
    if (!acquired || returnStarted) {
      return returnPromise;
    }

    returnStarted = true;
    returnPromise = (async () => {
      const method = iterator.return;
      if (typeof method === "function") {
        await method.call(iterator);
      }
    })();
    return returnPromise;
  }

  function makeEvent(source, number) {
    if (source.trim() === "") {
      return null;
    }

    try {
      return {
        line: number,
        ok: true,
        value: JSON.parse(source)
      };
    } catch {
      return {
        line: number,
        ok: false,
        text: source
      };
    }
  }

  async function next() {
    if (ended) {
      return done();
    }

    try {
      if (!acquired) {
        iterator = chunks[Symbol.asyncIterator]();
        acquired = true;
      }

      while (!ended) {
        if (offset < chunk.length) {
          const start = offset;
          while (offset < chunk.length && chunk[offset] !== 10) {
            offset++;
          }

          text += decoder.decode(chunk.subarray(start, offset), {
            stream: true
          });

          if (offset < chunk.length) {
            offset++;
            text += decoder.decode();

            let source = text;
            text = "";
            if (source.endsWith("\r")) {
              source = source.slice(0, -1);
            }

            const event = makeEvent(source, line++);
            if (event !== null) {
              return { done: false, value: event };
            }
          }

          continue;
        }

        chunk = new Uint8Array(0);
        offset = 0;

        const result = await iterator.next();
        if (ended) {
          return done();
        }

        if (result.done) {
          ended = true;
          text += decoder.decode();

          const source = text;
          text = "";
          const event = makeEvent(source, line);

          return event === null
            ? done()
            : { done: false, value: event };
        }

        chunk = result.value;
      }

      return done();
    } catch (error) {
      ended = true;
      text = "";
      chunk = new Uint8Array(0);
      offset = 0;

      try {
        await release();
      } catch {
        // Preserve the original reading error.
      }

      throw error;
    }
  }

  async function close() {
    if (ended) {
      await returnPromise;
      return;
    }

    ended = true;
    text = "";
    chunk = new Uint8Array(0);
    offset = 0;
    await release();
  }

  return { next, close };
}
